// Bun imports resolve to the native SQLite facade or an explicit runtime trap.
import { Database } from "bun:sqlite";
import * as ffi from "bun:ffi";

export const kind = typeof Database;
export const ptrKind = typeof ffi.FFIType.ptr;

export function open() {
  const db = new Database(":memory:");
  try {
    return String(db.query("SELECT 42 AS answer").get().answer);
  } finally {
    db.close();
  }
}

export function loadLibrary() {
  try {
    ffi.dlopen("unavailable-scriptc-test-library", {});
    return "loaded";
  } catch (e) {
    return String(e.message);
  }
}
